?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Long-tail SEO | TechSelectAI</title><style>body{font-family:system-ui;margin:0;background:#f5f7fa;color:#1f2937}.wrap{max-width:1180px;margin:auto;padding:24px}.grid{display:grid;grid-template-columns:360px 1fr;gap:18px}.panel{background:#fff;border:1px solid #dfe6ee;border-radius:14px;padding:16px}label{display:block;font-size:13px;font-weight:700;margin:10px 0 4px}input,select,button{width:100%;box-sizing:border-box;padding:9px;border:1px solid #cfd8e3;border-radius:8px;font:inherit}button{background:#173b63;color:#fff;font-weight:700;cursor:pointer;margin-top:12px}.card{border:1px solid #e5eaf0;border-radius:10px;padding:12px;margin:10px 0}.small{font-size:12px;color:#64748b}.good{color:#17603a}.warn{color:#8a5a00}.bad{color:#8a2525}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><h1>Long-tail SEO pages</h1><p class="small">Generate only evidence-backed buyer-intent pages. Every page is automatically evaluated by the #184 quality gate before publication/indexing.</p><div class="grid"><section class="panel"><h2>Generate page</h2><label>Template</label><select id="template"></select><label>Category</label><select id="category"><option value="">Select category</option></select><label>Product A / Primary product</label><select id="productA"><option value="">Select product</option></select><label>Product B</label><select id="productB"><option value="">Select product</option></select><label>Context label</label><input id="contextLabel" placeholder="Logistics companies"><label>Context value / slug</label><input id="contextValue" placeholder="logistics"><button id="generate">Generate and run quality gate</button><div class="small" id="msg"></div></section><section class="panel"><h2>Generated pages</h2><div id="pages"></div></section></div></div><script>let csrf='';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));async function load(){const r=await fetch('/api/long-tail-seo',{credentials:'same-origin'}),j=await r.json();if(!r.ok){msg.textContent=j.error||'Load failed';return;}csrf=j.csrf_token;template.innerHTML=Object.entries(j.templates).map(([k,v])=>`<option value="${esc(k)}">${esc(v)}</option>`).join('');category.innerHTML='<option value="">Select category</option>'+j.categories.map(x=>`<option value="${esc(x.slug)}">${esc(x.name)}</option>`).join('');const po='<option value="">Select product</option>'+j.products.map(x=>`<option value="${esc(x.slug)}">${esc(x.name)} · ${esc(x.category_slug)}</option>`).join('');productA.innerHTML=po;productB.innerHTML=po;pages.innerHTML=j.pages.length?j.pages.map(p=>`<article class="card"><strong>${esc(p.title)}</strong><div class="small">${esc(p.template_key)} · ${esc(p.context_label)} · <span class="${p.quality_decision==='indexable'?'good':p.quality_decision==='not_generated'?'bad':'warn'}">${esc(p.quality_decision)}</span> · score ${esc(p.quality_score??'—')}</div><div class="small">${esc(p.canonical_path)}</div>${p.reasons?.length?`<div class="small">Gate: ${esc(p.reasons.join(', '))}</div>`:''}${p.status==='published'?`<a href="${esc(p.canonical_path)}" target="_blank">Open page</a>`:''}</article>`).join(''):'<p class="small">No generated pages yet.</p>';}generate.onclick=async()=>{msg.textContent='';const body={template_key:template.value,category_slug:category.value,product_a_slug:productA.value,primary_product_slug:productA.value,product_b_slug:productB.value,context_label:contextLabel.value,context_value:contextValue.value};const r=await fetch('/api/long-tail-seo/generate',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(body)}),j=await r.json();msg.textContent=r.ok?`Generated: ${j.canonical_path} · ${j.quality.decision}`:(j.error||'Generation failed');if(r.ok)load();};load();</script></body></html>